(() => {
'use strict';
const lists={type:['Cushions','Throws','Rugs','Bedding','Curtains','Blinds','Towels','Bathmats','Table Linen'],colour:['Black','White','Cream','Beige','Brown','Grey','Green','Blue','Pink','Red','Orange','Yellow','Gold','Silver','Natural','Multi-colour'],material:['Cotton','Linen','Wool','Polyester','Velvet','Chenille','Faux Fur','Jute','Viscose','Acrylic','Mixed Fibre'],pattern:['Plain','Geometric','Striped','Checked','Floral','Botanical','Abstract','Animal','Textured','Patterned'],style:['Contemporary','Modern','Traditional','Scandi','Coastal','Rustic','Boho','Art Deco','Classic','Minimalist'],room:['Living Room','Bedroom','Dining Room','Bathroom','Kitchen','Hallway','Outdoor','Commercial / Hospitality'],shape:['Square','Rectangle','Round','Oval','Runner','Irregular / Organic'],use:['Indoor','Outdoor','Indoor & Outdoor'],care:['Machine Washable','Hand Wash','Spot Clean','Dry Clean','Wipe Clean'],pack:['Single','Pair','Set of 2','Set of 4','Multi-pack'],beddingSize:['Single','Double','King','Super King']};
const typeMap={'Cushion Pads':'Cushions','Seat & Bench Pads':'Cushions','Bench Pads':'Cushions','Seat and Bench Pads':'Cushions','Outdoor Cushions':'Cushions','Outdoor Throws':'Throws','Outdoor Cushions & Throws':['Cushions','Throws'],'Bed Linen':'Bedding',Bedspreads:'Bedding',Duvets:'Bedding',Pillows:'Bedding','Duvets & Pillows':'Bedding','Protectors & Toppers':'Bedding',Napkins:'Table Linen',Napkin:'Table Linen',Placemats:'Table Linen',Placemat:'Table Linen',Tablecloths:'Table Linen','Table Cloth':'Table Linen','Table Runners':'Table Linen','Table Runner':'Table Linen',Bathmat:'Bathmats',Towel:'Towels'};
const fields={pattern:['pattern','Pattern'],style:['style','Style'],room:['room','Room'],shape:['shape','Shape','Cushion Shape','Rug Shape'],use:['indoorOutdoor','Indoor / Outdoor','Suitability'],care:['care','Care'],pack:['pack','Pack / Set','Set / Pack'],filling:['cushionFilling','Cushion Filling','Filling'],pile:['rugConstruction','Rug Construction / Pile','Construction / Pile','Pile'],beddingSize:['beddingSize','Bedding Size','Bed Size'],heading:['curtainHeadingType','Curtain Heading Type','Heading Type'],lining:['lining','Lined / Unlined'],blindType:['blindType','Blind Type'],towelSize:['towelSize','Towel Size'],tableLinenType:['tableLinenType','Table Linen Type']};
const clean=v=>v!==undefined&&v!==null&&v!==''&&!['Not supplied','Not specified','Not applicable'].includes(v);
const raw=(p,k)=>(fields[k]||[k]).map(f=>p[f]).find(clean);
const stock={'In stock':'In Stock','In Stock':'In Stock',Incoming:'Due Soon / Incoming','Due soon':'Due Soon / Incoming','Due Soon':'Due Soon / Incoming','Due Soon / Incoming':'Due Soon / Incoming','Pre-order':'Pre-order'};
const aliases={shape:{Irregular:'Irregular / Organic',Organic:'Irregular / Organic'},pattern:{Herringbone:'Geometric',Stripes:'Striped',Checks:'Checked'},colour:{Multicolour:'Multi-colour','Multi Colour':'Multi-colour'},material:{'Mixed Fibres':'Mixed Fibre','Polyester Blend':'Mixed Fibre','Cotton Blend':'Mixed Fibre'}};
function values(p,k){let v=raw(p,k);if(k==='type')v=typeMap[p.type]||p.type;if(k==='use'&&!clean(v)&&/^Outdoor /.test(p.type))v='Outdoor';if(k==='tableLinenType'&&!clean(v)&&typeMap[p.type]==='Table Linen')v=p.type;return (Array.isArray(v)?v:[v]).filter(clean).map(x=>k==='availability'?stock[x]:aliases[k]?.[x]||x).filter(clean).filter(x=>!lists[k]||lists[k].includes(x)||(k==='shape'&&x==='Bolster'&&values(p,'type').includes('Cushions')));}
function numeric(p,k){const keys=k==='price'?['tradePrice','Trade Price']:k==='lengthHeight'?['lengthMm','length_mm','Length (mm)','heightMm','height_mm','Height (mm)','curtainDropMm','Curtain Drop (mm)']:['widthMm','width_mm','Width (mm)','curtainWidthMm','Curtain Width (mm)'];const v=keys.map(f=>p[f]).find(clean);return typeof v!=='boolean'&&v!==undefined&&Number.isFinite(Number(v))&&Number(v)>=0?Number(v):null;}
function configure(products,sub='',group=''){const scoped=!!sub||!!group;const types=[...products.flatMap(p=>values(p,'type')),...(sub?[typeMap[sub]||sub].flat():[]),...(group==='Cushions & Throws'?['Cushions','Throws']:group==='Bedding'?['Bedding']:group==='Rugs & Practical Textiles'?['Rugs']:group==='Kitchen & Table Linen'?['Table Linen']:group==='Outdoor Textiles'?['Cushions','Throws']:[])];
const cushion=scoped&&types.includes('Cushions'),rug=scoped&&types.includes('Rugs'),bedding=scoped&&types.includes('Bedding'),curtain=scoped&&types.includes('Curtains')&&products.filter(p=>values(p,'type').includes('Curtains')).length>=2,blind=scoped&&types.includes('Blinds'),towel=scoped&&types.some(t=>['Towels','Bathmats'].includes(t)),table=scoped&&types.includes('Table Linen');
const labels={type:'Product Type',width:curtain?'Curtain Width':'Width',lengthHeight:curtain?'Curtain Drop':blind?'Drop':'Length / Height',colour:'Colour',material:'Material',pattern:'Pattern',style:'Style',availability:'Availability',room:'Room'};
const facetOptions={...lists,material:[...new Set(products.flatMap(p=>values(p,'material')))]};
if(types.some(t=>['Cushions','Rugs','Bathmats','Table Linen'].includes(t))){labels.shape=cushion&&!rug?'Cushion Shape':rug&&!cushion?'Rug Shape':'Shape';if(cushion&&!rug)facetOptions.shape=['Square','Rectangle','Round','Bolster'];if(rug&&!cushion)facetOptions.shape=['Rectangle','Round','Runner','Oval','Irregular / Organic'];}
labels.use='Indoor / Outdoor';if(products.some(p=>values(p,'care').length))labels.care='Care';if(products.some(p=>values(p,'pack').length))labels.pack='Pack / Set';labels.price='Price';
if(cushion)labels.filling='Cushion Filling';if(rug&&products.some(p=>values(p,'pile').length))labels.pile='Rug Construction / Pile';if(bedding)labels.beddingSize='Bedding Size';
if(curtain){if(products.some(p=>values(p,'heading').length))labels.heading='Curtain Heading Type';if(products.some(p=>values(p,'lining').length))labels.lining='Lined / Unlined';}if(blind&&products.some(p=>values(p,'blindType').length))labels.blindType='Blind Type';if(towel&&products.some(p=>values(p,'towelSize').length))labels.towelSize='Towel Size';if(table)labels.tableLinenType='Table Linen Type';
return {labels,facetOptions,numericFacets:['width','lengthHeight','price'],textiles:true};}
window.TextilesFilters={configure,values,numeric};
})();
